import numpy as np, base64, struct, sys

def make_pcm(wave, periods, samples_per_period, dtype='int16'):
    n = periods*samples_per_period
    t = np.arange(n)
    if wave=='sine':
        x = np.sin(2*np.pi*periods*t/n)
    elif wave=='square':
        x = np.sign(np.sin(2*np.pi*periods*t/n))*0.9
    elif wave=='triangle':
        x = (2/np.pi)*np.arcsin(np.sin(2*np.pi*periods*t/n))*0.9
    elif wave=='saw':
        x = (2*(t/(samples_per_period) % 1) - 1)*0.8
    elif wave=='noise':
        x = np.random.uniform(-1,1,n)
    else:
        raise ValueError(wave)
    if dtype=='int16':
        xi = np.clip(x,-1,1)
        data = (xi*32767).astype('<i2')
        return base64.b64encode(data.tobytes()).decode()
    elif dtype=='float32':
        data = x.astype('<f4')
        return base64.b64encode(data.tobytes()).decode()

if __name__=='__main__':
    wave = sys.argv[1]
    periods = int(sys.argv[2])
    spp = int(sys.argv[3])
    print(make_pcm(wave, periods, spp))
