BASE = {'C':0,'C#':1,'Db':1,'D':2,'D#':3,'Eb':3,'E':4,'F':5,'F#':6,'Gb':6,
        'G':7,'G#':8,'Ab':8,'A':9,'A#':10,'Bb':10,'B':11}
def n(name):
    m = re.match(r'([A-G][#b]?)(\d)', name)
    return 49 + (int(m.group(2))-4)*12 + BASE[m.group(1)]

# ---- instruments ----
