import json, math

# Import C4speed = SR/2 = 22050 (SR=44100). output_freq(N)=native*11025/native? 
# Empirically: out(N) = native * 0.5 * 2^((N-49)/12)
# => for target freq T with ref note49 freq = native*0.5:  N = 49 + 12*log2(T/(native*0.5))
NATIVE = {1:523.7, 2:523.7, 3:132.3}  # lead, arp, bass
def note(target, inst):
    ref = NATIVE[inst]*0.5
    return round(49 + 12*math.log2(target/ref))

# chord notes by name->freq (equal temperament, A4=440)
A4=440.0
def f(name):
    base={'C':-9,'C#':-8,'D':-7,'D#':-6,'E':-5,'F':-4,'F#':-3,'G':-2,'G#':-1,'A':0,'A#':1,'B':2}
    m=__import__('re').match(r'([A-G]#?)(\d)',name)
    semi=base[m.group(1)]+(int(m.group(2))-4)*12
    return A4*2**(semi/12)
